function experience(n){g.xp+=n;while(g.xp>=g.level*60&&g.level<20){g.xp-=g.level*60;g.level++;g.maxHp=Math.min(300,g.maxHp+8);g.hp=Math.min(g.maxHp,g.hp+23);g.maxShield=Math.min(300,g.maxShield+6);if(g.shieldDelay===0)g.shield=Math.min(g.maxShield,g.shield+25);spawnLevelReward();notify(`自機Lv.${g.level} / 基礎攻撃力・HP・シールド成長／強化品を支給`);beep(900,.18)}}
