function weaponStats(level=weaponLevel()){return {range:115*(1+.08*(level-1)),doubleGap:.14/(1+.1*(level-1)),doubleCycle:.32/(1+.1*(level-1)),shotCount:2+Math.floor((level-1)/2),shotInterval:.16/(1+.12*Math.ceil((level-1)/2)),turnRate:Math.min(2.1,(level-1)*.3)}}
