function enemy(){const i=g.spawnIndex++,kind=i%5===0?'heavy':i%3===0?'rush':'scout';const level=spawningEnemyLevel(),stats=ENEMY_LEVELS[level],max=(kind==='heavy'?75:kind==='rush'?28:38)*stats.hp;g.enemies.push({x:65+Math.random()*770,y:-30,hp:max,max,level,attackScale:stats.attack,r:kind==='heavy'?24:17,kind,weight:BALANCE.weights[kind],knockX:0,knockY:0,shieldContact:0,touching:false,timer:1.7+Math.random(),age:0,dead:false})}
