function recoverBaseShield(dt){g.baseBreak=Math.max(0,g.baseBreak-dt);const regenDt=Math.max(0,dt-g.baseShieldCooldown);g.baseShieldCooldown=Math.max(0,g.baseShieldCooldown-dt);if(g.baseShieldDelay>0){g.baseShieldDelay=Math.max(0,g.baseShieldDelay-dt);if(g.baseShieldDelay===0){g.baseShield=g.maxBaseShield*.5;notify('拠点バリア再起動 / 50%');beep(650,.15)}}else g.baseShield=Math.min(g.maxBaseShield,g.baseShield+g.maxBaseShield*.01*regenDt)}

function displayPercent(value,max){return clamp(Math.ceil(value/max*100),0,100)}
function rewardRank(base){const percent=displayPercent(base,g.maxBase);return percent>=85?1:percent>=50?2:percent>=20?3:4}
const OPTION_NAMES={trail:'追従射撃型',side:'横並び射撃型',orbit:'周回近接型',laser:'前方レーザー',baseMissile:'拠点ミサイル',turret:'拠点砲台',defender:'防衛型オプション',aura:'攻撃オーラ',firework:'花火ミサイル',shockwave:'衝撃波'};
const OPTION_BADGES={trail:'O-T',side:'O-S',orbit:'O-R',laser:'O-L',baseMissile:'B-M',turret:'B-T',defender:'B-D',aura:'AUR',firework:'FW',shockwave:'SW'};
function pick(list){return list[Math.floor(Math.random()*list.length)]}
function rewardBuff(key,amount){return {kind:'buff',key,amount,label:(key==='hp'?'最大HP':'シールド性能（容量・回復）')+' +'+Math.round(amount*100)+'%'}}
function optionReward(){const option=pick(Object.keys(OPTION_NAMES));return {kind:'option',option,label:OPTION_NAMES[option]+' / 取得・同種強化'}}
function weaponReward(amount=1){return {kind:'weaponLevel',amount,label:'使用中の武器Lv. +'+amount}}
function optionUpgrade(amount=1){return {kind:'optionUpgrade',amount,label:'オプションLv. +'+amount+'（未所持なら配備）'}}
function levelReward(){return pick([rewardBuff('hp',.08),rewardBuff('shield',.08),weaponReward(),optionReward()])}
function spawnLevelReward(){g.supplies.push({kind:'reward',reward:levelReward(),x:100+Math.random()*700,y:BASE,age:0,dead:false})}
function rollRewards(rank){const amount=rank===1?.08:rank===2?.15:.25;const pool=[()=>rewardBuff('shield',amount),()=>optionReward()];if(rank===1)pool.push(()=>weaponReward(1));if(rank===3)pool.push(()=>({kind:'combinedUpgrade',label:'オプションLv. +1 ＆ 使用中の武器Lv. +1'}));if(rank>=2){pool.push(()=>weaponReward(rank===3?2:1),()=>optionUpgrade(rank===3?2:1),()=>weaponReward(rank===3?2:1))}
if(rank===4){const special=pick(['missile','laser']);return [{kind:'final',special,label:'最終武器：'+(special==='missile'?'アークミサイル':'ノヴァレーザー')}]}
return Array.from({length:5-rank},()=>pick(pool)())}
function spawnWaveRewards(){g.rewardRank=rewardRank(g.base);g.rewardBasePercent=displayPercent(g.base,g.maxBase);const rewards=rollRewards(g.rewardRank);g.rewardSummary=rewards.map(r=>r.label);rewards.forEach((reward,i)=>g.supplies.push({kind:'reward',reward,x:W*(i+1)/(rewards.length+1),y:BASE,age:0,dead:false}))}
function addOption(kind,amount=1){let option=g.options.find(o=>o.kind===kind);if(!option){option={kind,level:1,x:g.x,y:g.y,shot:0,age:0,mode:'ready',cooldown:0,target:null};g.options.push(option);amount--}option.level=Math.min(BALANCE.optionMax,option.level+amount)}
function applyReward(r){if(r.kind==='combinedUpgrade'){applyReward(weaponReward(1));applyReward(optionUpgrade(1));notify('取得 / '+r.label);return}if(r.kind==='buff'){if(r.key==='hp'){const extra=g.maxHp*r.amount;g.maxHp=Math.min(300,g.maxHp+extra);g.hp=Math.min(g.maxHp,g.hp+extra)}else if(r.key==='shield'){const extra=g.maxShield*r.amount;g.maxShield=Math.min(300,g.maxShield+extra);g.regenBonus=Math.min(2,g.regenBonus*(1+r.amount));if(g.shieldDelay===0)g.shield=Math.min(g.maxShield,g.shield+extra)}}else if(r.kind==='weaponLevel'){g.weaponLevels[weaponKey()]=Math.min(BALANCE.weaponMax,weaponLevel()+r.amount)}else if(r.kind==='option')addOption(r.option);else if(r.kind==='optionUpgrade'){const option=pick(g.options.filter(o=>o.level<BALANCE.optionMax));if(option)addOption(option.kind,r.amount);else if(g.options.length<Object.keys(OPTION_NAMES).length)addOption(pick(Object.keys(OPTION_NAMES).filter(k=>!g.options.some(o=>o.kind===k))),r.amount);else if(g.shieldDelay===0)g.shield=Math.min(g.maxShield,g.shield+20)}else{g.secondSlash=0;g.shot=0;if(r.kind==='final')g.special=r.special;else if(r.kind==='equipment'){g.weaponLevels[weaponKey()]=Math.min(BALANCE.weaponMax,weaponLevel()+Math.max(1,(r.level||2)-1))}}notify('取得 / '+r.label)}
function pushEnemy(e,power){let dx=e.x-g.x,dy=e.y-g.y;if(dy>=0){dx=dx===0?(e.x<W/2?-1:1):Math.sign(dx);dy=0}else if(Math.hypot(dx,dy)<1){dy=-1}const length=Math.hypot(dx,dy)||1;e.knockX=dx/length*power;e.knockY=dy/length*power;e.x=clamp(e.x+dx/length*10,e.r,W-e.r);e.y+=dy/length*10}
