if(e.dashing){const t=clamp(e.modeTime/.65,0,1);const old={x:e.x,y:e.y};e.x=e.origin.x+(e.target.x-e.origin.x)*t;e.y=e.origin.y+(e.target.y-e.origin.y)*t;if(segmentDistance(g,old,e)<e.r+14&&!e.dashHit){if(g.inv<=0)g.hp-=18;e.dashHit=true;e.touching=true;pushPlayer(e,e.stage===3?420:240)}if(e.modeTime>=.65)e.dashing=false}
if(e.stage===2&&n===3&&e.phase===2&&e.modeTime>.7&&!e.secondLeap){e.x=W-e.target.x;e.secondLeap=true}
const stream=(e.stage===3&&n===1)||(e.stage===4&&(n===0||n===3))||(e.stage===6&&n===3&&e.phase===2);if(stream&&e.modeTime>=e.nextShot){e.nextShot=e.modeTime+.22;const targetAngle=Math.atan2(g.y-e.y,g.x-e.x);if(e.stage===4&&n===3){const side=e.counter%2?1:-1;bossBullet(e.x+side*90,e.y+35,targetAngle)}else if(e.stage===4){for(const side of [-1,1])bossBullet(e.x+side*14,e.y+30,Math.PI/2)}else if(e.stage===6)bossFan(e,5,1.1,Math.PI/2+Math.sin(e.modeTime*3)*.6);else bossBullet(e.x,e.y+30,targetAngle);e.counter++}
