function campaignReport(){if(!g.stageResults.length)return "";return '<details class="campaign-report"><summary>ステージ別の戦績</summary>'+g.stageResults.map(r=>`<p>${r.stage} ${r.name} / RANK ${r.rank}<br>${r.seconds}秒（ボス${r.bossSeconds}秒）・自機被害${r.damage}・拠点被害${r.baseDamage}・取得${r.equipment}個</p>`).join("")+"</details>"}

// Option levels change damage only, except laser levels increase beam count.
const OPTION_TUNING={trail:{damage:6,interval:.65},side:{damage:5,interval:.85},orbit:{damage:16,radius:75},laser:{damage:20,interval:1.5,length:500,width:8},baseMissile:{damage:32,blast:24,interval:3.2,radius:85,knock:340},turret:{damage:10,interval:.75,range:320},defender:{damage:25,radius:100,range:280,speed:430,rest:2,knock:500},aura:{damage:22,radius:95,cycle:4,active:1.8},firework:{damage:24,blast:24,interval:2.2,radius:95},shockwave:{damage:20,interval:3.5,radius:145,knock:280}};
function optionDamage(o,key='damage'){return OPTION_TUNING[o.kind][key]*(o.kind==='laser'?1:1+.25*(o.level-1))}
function optionTargets(){return g.enemies.filter(e=>!e.dead&&e.y>=0&&e.y<BASE)}
function nearestOptionEnemy(p,range=Infinity){return optionTargets().filter(e=>distance(p,e)<=range).sort((a,b)=>distance(p,a)-distance(p,b))[0]}
function optionPush(e,power){if(e.dead)return;upward(e,power);if(e.boss){e.y=Math.max(65,e.y-power*.05);if(e.dashing){e.dashing=false;e.mode='recover';e.modeTime=0}}}
function optionBlast(x,y,r,damage,knock=0,color='#ffd18c'){for(const e of [...optionTargets()])if(!g.bossDefeated&&distance({x,y},e)<=r+e.r){damageEnemy(e,damage);if(knock)optionPush(e,knock)}g.optionFX.push({kind:'burst',x,y,r,life:.4,max:.4,color})}
function optionShot(o,x,y,vx,vy,extra={}){g.optionShots.push({x,y,vx,vy,r:5,life:4,damage:optionDamage(o),kind:o.kind,...extra})}
function updateOptions(dt){if(g.bossDefeated)return;g.optionFX=g.optionFX.filter(f=>{f.life-=dt;return f.life>0||(f.kind==='wave'&&f.r<f.limit)});for(const o of g.options){if(g.bossDefeated)break;const cfg=OPTION_TUNING[o.kind];o.age=(o.age||0)+dt;o.shot=Math.max(0,o.shot-dt);const damage=optionDamage(o);if(o.kind==='trail'){o.x+=(g.x-o.x)*Math.min(1,dt*6);o.y+=(g.y+40-o.y)*Math.min(1,dt*6)}else if(o.kind==='side'){o.x=g.x;o.y=g.y}else if(o.kind==='orbit'){o.x=g.x+Math.cos(o.age*3)*cfg.radius;o.y=g.y+Math.sin(o.age*3)*cfg.radius}else if(o.kind==='baseMissile'){o.x=280;o.y=BASE-10}else if(o.kind==='turret'){o.x=620;o.y=BASE-10}else if(o.kind!=='defender'){o.x=g.x;o.y=g.y-(o.kind==='laser'?45:0)}
if(o.kind==='orbit'){for(const e of optionTargets())if(distance(o,e)<e.r+11)damageEnemy(e,damage*dt);continue}
if(o.kind==='aura'){o.active=o.age%cfg.cycle<cfg.active;if(o.active)for(const e of optionTargets())if(distance(g,e)<cfg.radius+e.r)damageEnemy(e,damage*dt);continue}
if(o.kind==='defender'){updateDefender(o,dt);continue}
if(o.shot>0)continue;const target=nearestOptionEnemy(o);if(!target)continue;
if(o.kind==='trail'){const angle=Math.atan2(target.y-o.y,target.x-o.x);optionShot(o,o.x,o.y,Math.cos(angle)*650,Math.sin(angle)*650)}
if(o.kind==='side')for(const side of [-1,1])optionShot(o,g.x+side*55,g.y-10,0,-650);
if(o.kind==='laser'){for(let i=0;i<o.level;i++){const x=g.x+(i-(o.level-1)/2)*26,a={x,y:o.y},b={x,y:Math.max(-20,o.y-cfg.length)};for(const e of optionTargets())if(segmentDistance(e,a,b)<e.r+cfg.width)damageEnemy(e,damage);g.optionFX.push({kind:'laser',offset:x-g.x,length:cfg.length,width:cfg.width,life:.18,max:.18,color:'#80f1ed'})}}
if(o.kind==='baseMissile'){const enemy=pick(optionTargets());optionShot(o,o.x,o.y,0,-310,{r:8,target:enemy,homing:true,blast:optionDamage(o,'blast'),radius:cfg.radius,knock:cfg.knock})}
if(o.kind==='turret'){const enemy=nearestOptionEnemy(o,cfg.range);if(!enemy)continue;const angle=Math.atan2(enemy.y-o.y,enemy.x-o.x);o.angle=angle;optionShot(o,o.x,o.y,Math.cos(angle)*1000,Math.sin(angle)*1000,{r:4})}
if(o.kind==='firework')optionShot(o,g.x,g.y-20,0,-450,{r:7,blast:optionDamage(o,'blast'),radius:cfg.radius});
if(o.kind==='shockwave'){g.optionFX.push({kind:'wave',x:g.x,y:g.y,r:0,limit:cfg.radius,speed:360,damage,knock:cfg.knock,hits:new Set(),life:cfg.radius/360,max:cfg.radius/360,color:'#c6c0ff'})}
o.shot=cfg.interval;
}
for(const s of g.optionShots){if(g.bossDefeated)break;s.life-=dt;const prev={x:s.x,y:s.y};if(s.homing){if(!s.target||s.target.dead)s.target=pick(optionTargets());if(s.target){const a=Math.atan2(s.vy,s.vx),desired=Math.atan2(s.target.y-s.y,s.target.x-s.x),delta=Math.atan2(Math.sin(desired-a),Math.cos(desired-a)),angle=a+clamp(delta,-3*dt,3*dt);s.vx=Math.cos(angle)*310;s.vy=Math.sin(angle)*310}}s.x+=s.vx*dt;s.y+=s.vy*dt;const hits=optionTargets().filter(e=>segmentDistance(e,prev,s)<e.r+s.r).sort((a,b)=>distance(prev,a)-distance(prev,b));if(hits.length){const e=hits[0];s.dead=true;s.x=e.x;s.y=e.y;damageEnemy(e,s.damage);if(s.blast&&!g.bossDefeated){optionBlast(s.x,s.y,s.radius,s.blast,s.knock||0,s.kind==='firework'?'#ffb5ed':'#ffd18c');if(s.kind==='firework')particles(s.x,s.y,'#ffb5ed',26)}}}
g.optionShots=g.optionShots.filter(s=>!s.dead&&s.life>0&&s.x>-50&&s.x<W+50&&s.y>-50&&s.y<H+50);
for(const f of g.optionFX)if(f.kind==='wave'){const before=f.r;f.r=Math.min(f.limit,f.r+f.speed*dt);for(const e of optionTargets())if(!g.bossDefeated&&!f.hits.has(e)&&distance(f,e)<=f.r+e.r&&distance(f,e)>=before-e.r){f.hits.add(e);damageEnemy(e,f.damage);optionPush(e,f.knock)}}
}
function updateDefender(o,dt){const cfg=OPTION_TUNING.defender,home={x:450,y:BASE-95};if(!o.initialized){o.x=home.x;o.y=home.y;o.initialized=true}if(o.mode==='rest'){o.cooldown=Math.max(0,o.cooldown-dt);if(o.cooldown===0)o.mode='return';return}if(o.mode==='ready'){o.target=nearestOptionEnemy(home,cfg.range);if(o.target)o.mode='charge';else return}if(o.mode==='charge'&&(!o.target||o.target.dead))o.mode='return';const target=o.mode==='charge'?o.target:home;const d=distance(o,target),move=Math.min(d,cfg.speed*dt);if(d>0){o.x+=(target.x-o.x)/d*move;o.y+=(target.y-o.y)/d*move}if(o.mode==='charge'&&distance(o,target)<target.r+18){optionBlast(o.x,o.y,cfg.radius,optionDamage(o),cfg.knock,'#a8efcc');o.mode='rest';o.cooldown=cfg.rest;o.target=null}else if(o.mode==='return'&&distance(o,home)<1)o.mode='ready'}
function drawOptions(){ctx.save();for(const o of g.options){const base=['baseMissile','turret','defender'].includes(o.kind),color=base?'#a8efcc':o.kind==='firework'?'#ffb5ed':'#99d8ff';if(o.kind==='aura'){if(o.active){ctx.fillStyle='#dbacfa19';ctx.strokeStyle='#ddb8ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(g.x,g.y,OPTION_TUNING.aura.radius,0,Math.PI*2);ctx.fill();ctx.stroke()}continue}if(o.kind==='shockwave')continue;const points=o.kind==='side'?[{x:g.x-55,y:g.y},{x:g.x+55,y:g.y}]:[o];for(const p of points){ctx.globalAlpha=o.mode==='rest'?.35:1;ctx.fillStyle=color;if(base){ctx.fillRect(p.x-12,p.y-10,24,20);ctx.strokeStyle=color;ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(p.x,p.y);const a=o.kind==='turret'?(o.angle||-Math.PI/2):-Math.PI/2;ctx.lineTo(p.x+Math.cos(a)*23,p.y+Math.sin(a)*23);ctx.stroke()}else{ctx.beginPath();ctx.arc(p.x,p.y,9,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#102332';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText(o.level,p.x,p.y+4)}}ctx.globalAlpha=1;
for(const s of g.optionShots){ctx.fillStyle=s.kind==='firework'?'#ffb5ed':s.kind==='baseMissile'?'#ffd18c':'#99d8ff';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill()}
for(const f of g.optionFX){ctx.globalAlpha=clamp(f.life/f.max,0,1);ctx.strokeStyle=f.color;ctx.lineWidth=f.kind==='laser'?f.width*2:4;ctx.beginPath();if(f.kind==='laser'){ctx.moveTo(g.x+f.offset,g.y-45);ctx.lineTo(g.x+f.offset,Math.max(-20,g.y-45-f.length))}else{ctx.arc(f.x,f.y,f.r,0,Math.PI*2);if(f.kind==='burst')for(let i=0;i<12;i++){const a=i*Math.PI/6;ctx.moveTo(f.x+Math.cos(a)*f.r*.3,f.y+Math.sin(a)*f.r*.3);ctx.lineTo(f.x+Math.cos(a)*f.r,f.y+Math.sin(a)*f.r)}}ctx.stroke()}ctx.restore()}

function bossBonusChoices(){const choices=[];const add=(id,label,detail,apply)=>choices.push({id,label,detail,apply});if(g.maxHp<300)add('hp','最大HP +10%',Math.ceil(g.maxHp)+' → '+Math.ceil(Math.min(300,g.maxHp+g.maxHp*.1)),()=>applyReward(rewardBuff('hp',.1)));if(g.maxShield<300||g.regenBonus<2)add('shield','自機シールド性能 +10%','容量 '+Math.ceil(g.maxShield)+' → '+Math.ceil(Math.min(300,g.maxShield+g.maxShield*.1))+' / 回復倍率 '+g.regenBonus.toFixed(2)+' → '+Math.min(2,g.regenBonus*1.1).toFixed(2),()=>applyReward(rewardBuff('shield',.1)));add('base','拠点最大耐久 +10%',Math.ceil(g.maxBase)+' → '+Math.ceil(g.maxBase+g.maxBase*.1),()=>{const gain=g.maxBase*.1;g.maxBase+=gain;g.base=Math.min(g.maxBase,g.base+gain)});add('baseShield','拠点シールド容量 +10%',Math.ceil(g.maxBaseShield)+' → '+Math.ceil(g.maxBaseShield+g.maxBaseShield*.1),()=>{const gain=g.maxBaseShield*.1;g.maxBaseShield+=gain;if(g.baseShieldDelay===0)g.baseShield=Math.min(g.maxBaseShield,g.baseShield+gain)});if(weaponLevel()<BALANCE.weaponMax)add('weapon','使用中の武器Lv. +1',weaponName()+' → Lv.'+(weaponLevel()+1),()=>applyReward(weaponReward()));for(const o of g.options)if(o.level<BALANCE.optionMax)add('option-'+o.kind,OPTION_NAMES[o.kind]+' Lv. +1','Lv.'+o.level+' → '+(o.level+1)+(o.kind==='laser'?' / レーザー本数 +1':' / 基礎威力の25%を加算'),()=>addOption(o.kind));return choices}
function openBossBonus(){state='bonus';$('overlay').classList.toggle('bonus-overlay',true);keys.clear();g.bonusChoices=bossBonusChoices();g.bonusIndex=0;g.bonusDirection=0;g.bonusReady=false;g.bonusConfirmHeld=true;$('pause').textContent='強化を選択中';const options=g.options.map(o=>OPTION_NAMES[o.kind]+' Lv.'+o.level+(o.level>=BALANCE.optionMax?'（上限）':'')).join(' ／ ')||'未取得';$('overlay').style.display='grid';$('overlay').innerHTML='<div class="panel bonus-panel"><div class="eyebrow">STAGE '+g.stage+' CLEAR / RANK '+stageRank()+'</div><h1>ボス撃破ボーナス</h1><h2>どのステータスを強化しますか？</h2><div class="bonus-summary"><p>自機HP '+Math.ceil(g.hp)+' / '+Math.ceil(g.maxHp)+'　シールド '+Math.ceil(g.shield)+' / '+Math.ceil(g.maxShield)+'<br>拠点耐久 '+Math.ceil(g.base)+' / '+Math.ceil(g.maxBase)+'　拠点シールド '+Math.ceil(g.baseShield)+' / '+Math.ceil(g.maxBaseShield)+'<br>自機Lv.'+g.level+'　SP '+Math.floor(g.spirit)+'%　シールド回復倍率 '+g.regenBonus.toFixed(2)+'</p><p>武器：'+weaponName()+'</p><p>取得オプション：'+options+'</p></div><p class="muted">時間制限なし。1つ選んで強化できます。上限の装備は一覧表示のみ。</p><div class="bonus-choices">'+g.bonusChoices.map((c,i)=>'<button id="bonus-'+i+'" class="bonus-choice"><strong>'+c.label+'</strong><small>'+c.detail+'</small></button>').join('')+'</div><button id="bonus-confirm" class="primary">選んだ項目を強化して進む</button><p class="muted">マウスで選択 → 決定 ／ W・A：前へ、S・D：次へ ／ Enter・Space：決定<br>ゲームパッド：方向入力で選択、攻撃ボタンで決定</p></div>';g.bonusChoices.forEach((c,i)=>{$('bonus-'+i).onclick=()=>{g.bonusIndex=i;highlightBossBonus()}});$('bonus-confirm').onclick=confirmBossBonus;highlightBossBonus(false);updateHud()}
function highlightBossBonus(reveal=true){g.bonusChoices.forEach((c,i)=>{const el=$('bonus-'+i);el.classList.toggle('selected',i===g.bonusIndex);el.setAttribute?.('aria-pressed',String(i===g.bonusIndex))});if(reveal)$('bonus-'+g.bonusIndex).scrollIntoView?.({block:'nearest'})}
function handleBonusInput(x,y,confirm){const dir=Math.abs(y)>.5?Math.sign(y):Math.abs(x)>.5?Math.sign(x):0;if(!g.bonusReady){if(!dir&&!confirm){g.bonusReady=true;g.bonusConfirmHeld=false}return}if(dir&&dir!==g.bonusDirection){g.bonusIndex=(g.bonusIndex+dir+g.bonusChoices.length)%g.bonusChoices.length;highlightBossBonus()}g.bonusDirection=dir;if(confirm&&!g.bonusConfirmHeld)confirmBossBonus();g.bonusConfirmHeld=confirm}
function confirmBossBonus(){if(state!=='bonus')return;const choice=g.bonusChoices[g.bonusIndex];if(!choice)return;choice.apply();g.stageResults.at(-1).bossBonus=choice.label;state='playing';keys.clear();previous={};$('overlay').classList.toggle('bonus-overlay',false);$('overlay').style.display='none';$('pause').textContent='一時停止';notify('ボス撃破ボーナス / '+choice.label);updateHud()}

